class Card:
    def __init__(self, mark):
        self.mark = mark
    def passed(self):
        return self.mark >= 40


def main():
    print(Card(40).passed(), Card(39).passed())


if __name__ == "__main__":
    main()

class Counter:
    def __init__(self):
        self.value = 1


def main():
    a = Counter()
    b = a
    b.value += 1
    print(a.value)


if __name__ == "__main__":
    main()

class Seat:
    room = "A"


def main():
    a, b = Seat(), Seat()
    a.room = "B"
    print(a.room, b.room)


if __name__ == "__main__":
    main()
